mapper.insert:

  SELECT LPAD(SEQ_BLDG_ID.NEXTVAL, 10, '0') FROM DUAL

INSERT INTO BUILDING (
  BLDG_ID, RENTAL_PTY_ID, BLDG_NM, BLDG_ZIP_NO, BLDG_ADDR,
  BLDG_DTL_ADDR, BLDG_TYPE_CODE, BLDG_FLR_CNT, BLDG_UNIT_CNT,
  BLDG_CMPLTN_DT, BLDG_GROSS_AREA, BLDG_IMG_PATH, DEL_YN
) VALUES (
  #{bldgId}, #{rentalPtyId}, #{bldgNm}, #{bldgZipNo}, #{bldgAddr},
  #{bldgDtlAddr}, #{bldgTypeCode}, #{bldgFlrCnt}, #{bldgUnitCnt},
  #{bldgCmpltnDt}, #{bldgGrossArea}, #{bldgImgPath}, #{delYn}
)

mapper.update:
UPDATE BUILDING
SET DEL_YN = 'Y'
WHERE BLDG_ID = #{bldgId}
AND RENTAL_PTY_ID = #{rentalPtyId}

mapper.select:
SELECT *
FROM BUILDING
WHERE DEL_YN = 'N'
  AND RENTAL_PTY_ID = #{rentalPtyId}

  AND BLDG_NM LIKE '%' || #{searchBuildingName} || '%'


  -- 호수는 연관 테이블 있으면 JOIN, 없으면 조건 생략


  AND BLDG_TYPE_CODE = #{searchStatus}


  AND BLDG_TYPE_GROUP_CD = #{searchType}


  AND BLDG_CMPLTN_DT >= #{searchRegDateFrom}


  AND BLDG_CMPLTN_DT <= #{searchRegDateTo}

ORDER BY BLDG_ID ASC
